def solve_n_queens(n):
    def is_safe(board, row, col):
        for i in range(row):
            if board[i] == col or abs(board[i] - col) == abs(i - row):
                return False
        return True

    def backtrack(row):
        if row == n:
            return board[:]
        for col in range(n):
            if is_safe(board, row, col):
                board[row] = col
                result = backtrack(row + 1)
                if result:
                    return result
        return None

    board = [-1] * n
    return backtrack(0)

solution = solve_n_queens(7)
print(solution)
